mapper.select:
/* CommonLoginMapper.selectLoginList */ SELECT A.* FROM ( SELECT ROWNUM AS RNUM, A.* FROM ( SELECT AI_INPT_USER_ID AS ID, AI_INPT_USER_ENO AS ENO, AI_INPT_AUT_CD AS AUTH, AI_INPT_MGPE_YN AS ADMIN_YN, AI_INPT_USER_NM AS NAME, AI_INPT_USER_YN FROM CSPD101TI WHERE 1=1
ORDER BY ID ASC ) A
WHERE ROWNUM <= #{lastIndex}
) A
WHERE ROWNUM >= #{firstIndex}

/* CommonLoginMapper.selectLoginTime */
	SELECT A.AI_INPT_LGIN_DTM
	  FROM (
			SELECT
				TO_CHAR(TO_DATE(SUBSTR(AI_INPT_LGIN_DTM,1,14),'YYYYMMDDHH24MISS'),'YYYY-MM-DD HH24:MI:SS') AS AI_INPT_LGIN_DTM,
				ROW_NUMBER()OVER(ORDER BY AI_INPT_LGIN_DTM DESC) AS RN
			FROM CSPD810TH
			WHERE AI_INPT_LGIN_USER_NO = #{id}  
	        ) A
	 WHERE A.RN = 1
